`rg -n 'Pic0CriticalPath|Pic0FiniteGaloisRepresentable|Pic0GaloisInvariantMatch' MainProjects/Algebraic-Jacobian-Challenge-Rebuild --glob '*.lean'`,
`sed -n '1,180p' MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian.lean`,
