`rg -n --pcre2 '\\b(pic0_representableBy|pic0RepresentableBy|jacobianData|JacobianData)\\b' MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian --glob '*.lean' | head -300`,
